pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        // Keep the input domain wide; assume at least one recipient.
        vm.assume(_tos.length > 0);

        // Deploy an adversarial callee that always reverts on transferFrom.
        // The fuzzer cannot synthesize a failing contract from a raw address,
        // so we deploy a minimal helper.
        FailingCallee failing = new FailingCallee();

        // Use the helper as the callee (caddress).
        address helperAddr = address(failing);

        // Ensure the caller (from) has no special role; prank as from.
        vm.prank(from);
        bool success = c.transfer(from, helperAddr, _tos, v);

        // Rule: if C.transfer returns true, it MUST be that the callee was NOT the
        // failing helper (which always reverts). If the helper is used, the correct
        // contract would revert, so success should never be true. The buggy mutant
        // ignores the revert and returns true.
        assertTrue(!success);
    }
}

/// @notice Minimal adversarial contract: every call to transferFrom reverts.
contract FailingCallee {
    fallback() external payable {
        revert("FailingCallee: forced failure");
    }
}

