pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        // 1. Domain: we need at least one target and caddress must be a contract (this test deploys a helper)
        vm.assume(_tos.length > 0);
        // 2. Deploy an adversarial helper that simulates a token - always returns true so calls succeed,
        //    but reverts on certain addresses to break the mutant's property
        TokenHelper helper = new TokenHelper();
        // Use the helper as the token contract
        caddress = address(helper);

        // 3. First transfer: all targets must succeed (helper always returns true)
        bool firstOk = true;
        try c.transfer(from, caddress, _tos, v) { firstOk = true; } catch { firstOk = false; }

        // If first succeeded, try a subset (just first element) - should also succeed
        // The mutant returns true even if the second call fails, but the reference reverts
        bool subOk = true;
        if (firstOk) {
            address[] memory subTos = new address[](1);
            subTos[0] = _tos[0];
            try c.transfer(from, caddress, subTos, v) { subOk = true; } catch { subOk = false; }
        }

        // Property: if first succeeded, subset must also succeed
        // The mutant violates this because it ignores failures, but here we check the invariant holds for reference
        assertTrue(!firstOk || subOk);
    }
}

contract TokenHelper {
    function transferFrom(address, address to, uint256) external pure returns (bool) {
        // Fail for addresses with a specific pattern to create a difference
        // This is the adversarial behavior: some targets make the call fail
        if (uint160(to) % 2 == 1) revert();
        return true;
    }
}

