pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0 && _tos.length <= 10);
        vm.assume(v < type(uint256).max);

        // Deploy an adversarial callee that only succeeds when the sent amount equals v
        SelectiveCallee callee = new SelectiveCallee(v);

        bool ok;
        try c.transfer(from, address(callee), _tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }

        // Reference C: transfer always returns true because the callee receives exactly v and succeeds.
        // Buggy M: transfer uses v+1, which SelectiveCallee rejects, so the external call reverts and transfer fails.
        assertTrue(ok);
    }
}

// Minimal adversarial callee: accepts a transferFrom call only when the amount equals an expected value.
contract SelectiveCallee {
    uint256 immutable expected;
    constructor(uint256 _expected) { expected = _expected; }
    function transferFrom(address, address, uint256 amount) external pure returns (bool) {
        // Succeeds only if amount matches the expected value (hardcoded at deploy but parameterized via fuzzed v).
        // The callee never reverts, but returns false on mismatch, triggering require(_s) in C/M.
        // We need the call to revert when amount != expected. So we revert instead.
        require(amount == expected, "unexpected amount");
        return true;
    }
}

