pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 length, uint256 seed) public {
        // admissible domain: length >= 1, seed used to generate deterministic addresses
        length = bound(length, 1, 10);
        address[] memory tos = new address[](length);
        for (uint256 i = 0; i < length; i++) {
            tos[i] = address(uint160(uint256(keccak256(abi.encode(seed, i)))));
        }
        address caddress = address(uint160(uint256(keccak256(abi.encode("caddress", seed)))));
        address from = address(uint160(uint256(keccak256(abi.encode("from", seed)))));
        uint v = 123;

        // Deploy a minimal "spy" callee that records which recipients get called
        Spy spy = new Spy(from);
        // The outer C will call the spy. The spy requires that msg.sender == from (for transferFrom semantics)
        // We'll prank as 'from' when calling transfer, and the spy checks msg.sender == from.
        vm.startPrank(from);
        spy.reset();
        try c.transfer(from, address(spy), tos, v) returns (bool ok) {
            // success
        } catch {
            // The correct version never reverts if spy behaves; accept catch to compare outcomes
        }
        vm.stopPrank();

        // The invariant: ALL tos addresses were called by the callee
        for (uint256 i = 0; i < length; i++) {
            assertTrue(spy.wasCalled(tos[i]));
        }
    }
}

// Adversarial callee that records calls and checks msg.sender == expectedFrom
contract Spy {
    address public expectedFrom;
    mapping(address => bool) public called;

    constructor(address _expectedFrom) {
        expectedFrom = _expectedFrom;
    }

    function reset() external {
        delete expectedFrom; // harmless; we don't reset mapping
        expectedFrom = address(msg.sender); // tricky but not needed; remove
        // Better: resetting mapping is expensive; we'll just rely on fresh fuzz seeds
    }

    // Fallback to record calls
    fallback() external payable {
        // decode recipient from calldata: function transferFrom(address,address,uint256)
        // selector 0x23b872dd
        (address _sender, address _recipient,) = abi.decode(msg.data[4:], (address, address, uint256));
        require(_sender == expectedFrom, "wrong from");
        called[_recipient] = true;
    }

    function wasCalled(address a) external view returns (bool) {
        return called[a];
    }
}

